result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/attribution.py", "content": """"Landing-page attribution and bounce-rate analysis."""

from collections import defaultdict

from generator import PAGES


def attribute(sessions: list[dict]) -> list[dict]:
    """Compute per-landing-page metrics.

    Returns rows sorted by conversion rate descending:
      landing_page, sessions, bounce_rate, avg_depth, conversions, conversion_rate
    """
    agg = {
        p: {"sessions": 0, "bounces": 0, "depth_sum": 0, "conversions": 0}
        for p in PAGES
    }

    for s in sessions:
        a = agg[s["landing_page"]]
        a["sessions"] += 1
        depth = len(s["pages"])
        a["depth_sum"] += depth
        if s["bounced"]:
            a["bounces"] += 1
        if s["converted"]:
            a["conversions"] += 1

    rows = []
    for page, a in agg.items():
        n = a["sessions"]
        rows.append(
            {
                "landing_page": page,
                "sessions": n,
                "bounce_rate": a["bounces"] / n if n else 0.0,
                "avg_depth": a["depth_sum"] / n if n else 0.0,
                "conversions": a["conversions"],
                "conversion_rate": a["conversions"] / n if n else 0.0,
            }
        )

    rows.sort(key=lambda r: r["conversion_rate"], reverse=True)
    return rows


def format_table(rows: list[dict]) -> str:
    header = (
        f"{'landing_page':<12} {'sessions':>8} {'bounce_rate':>12} "
        f"{'avg_depth':>10} {'conversions':>12} {'conv_rate':>10}"
    )
    lines = [header, "-" * len(header)]
    for r in rows:
        lines.append(
            f"{r['landing_page']:<12} {r['sessions']:>8} {r['bounce_rate']:>12.4f} "
            f"{r['avg_depth']:>10.2f} {r['conversions']:>12} {r['conversion_rate']:>10.4f}"
        )
    return "\n".join(lines)


if __name__ == "__main__":
    from generator import generate_sessions

    print(format_table(attribute(generate_sessions())))
