from generator import (
    BOUNCE_PROB,
    N_SESSIONS,
    PAGES,
    SEED,
    SIGNUP,
    generate_sessions,
)
from attribution import attribute, format_table

PLANTED_CONV = {p: (0.08 if p == "/pricing" else 0.02) for p in PAGES}


def sessions():
    return generate_sessions(seed=SEED, n=N_SESSIONS)


def by_page(rows):
    return {r["landing_page"]: r for r in rows}


def test_bounce_rates_recovered():
    rows = by_page(attribute(sessions()))
    for page, planted in BOUNCE_PROB.items():
        assert abs(rows[page]["bounce_rate"] - planted) < 0.03, page


def test_pricing_conversion_rate_highest_and_near_planted():
    rows = sorted(attribute(sessions()), key=lambda r: r["conversion_rate"], reverse=True)
    top = rows[0]
    assert top["landing_page"] == "/pricing"
    assert abs(top["conversion_rate"] - 0.08) <= 0.015
    # strictly the highest
    assert all(r["conversion_rate"] < top["conversion_rate"] for r in rows[1:])


def test_session_counts_sum_to_total():
    rows = attribute(sessions())
    total = sum(r["sessions"] for r in rows)
    assert total == N_SESSIONS


def test_bounce_implies_depth_one_in_attribution_input():
    for s in sessions():
        if s["bounced"]:
            assert len(s["pages"]) == 1


def test_generator_invariants():
    for s in generate_sessions(seed=SEED, n=N_SESSIONS):
        assert s["pages"][0] == s["landing_page"]
        if s["bounced"]:
            assert len(s["pages"]) == 1
            assert not s["converted"]
        if s["converted"]:
            assert SIGNUP in s["pages"]
            assert len(s["pages"]) >= 2
        assert 2 <= len(s["pages"]) <= 9 or s["bounced"] or len(s["pages"]) <= 9


def test_output_table_sorted_by_conversion_rate_desc():
    rows = attribute(sessions())
    rates = [r["conversion_rate"] for r in rows]
    assert rates == sorted(rates, reverse=True)


def test_table_rendering_matches_row_order():
    rows = attribute(sessions())
    table = format_table(rows)
    lines = [l for l in table.splitlines()[2:] if l.strip()]
    rendered_pages = [l.split()[0] for l in lines]
    assert rendered_pages == [r["landing_page"] for r in rows]


def test_conversions_match_planted_probabilities():
    rows = by_page(attribute(sessions()))
    for page, planted in PLANTED_CONV.items():
        tol = 0.015 if page == "/pricing" else 0.02
        assert abs(rows[page]["conversion_rate"] - planted) <= tol, page
